#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int k;
    cin >> n >> k;

    vector<long long> factors;
    long long remaining = n;

    for (long long p = 2; p * p <= remaining; ++p) {
        while (remaining % p == 0) {
            factors.push_back(p);
            remaining /= p;
        }
    }
    if (remaining > 1) factors.push_back(remaining);

    if (static_cast<int>(factors.size()) < k) {
        cout << -1;
        return 0;
    }

    for (int i = 0; i < k - 1; ++i) {
        cout << factors[i] << ' ';
    }

    long long last = 1;
    for (size_t i = k - 1; i < factors.size(); ++i) {
        last *= factors[i];
    }
    cout << last;

    return 0;
}

